package com.smartparking;
import com.smartparking.model.*;import com.smartparking.service.ParkingService;import com.smartparking.strategy.NearestSlotStrategy;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ParkingServiceTest {
 @Test void duplicateRegistrationRejected(){ParkingService s=new ParkingService();s.register(new Car("ABC123","Owner"));assertThrows(IllegalArgumentException.class,()->s.register(new Car("ABC123","Other")));}
 @Test void nearestCompatibleSlotSelected(){ParkingService s=new ParkingService(new NearestSlotStrategy(),List.of(new ParkingSlot("far",1,3,20),new ParkingSlot("near-small",1,1,2),new ParkingSlot("near",1,2,5)));s.register(new Car("ABC123","Owner"));assertEquals("near",s.enter("ABC123").slot().getId());}
 @Test void fullLotQueuesVehicleAndExitPromotesWaitingVehicle(){ParkingSlot slot=new ParkingSlot("s",1,1,1);ParkingService s=new ParkingService(new NearestSlotStrategy(),List.of(slot));s.register(new Bike("BIK123","Owner"));s.register(new Bike("BIK456","Owner"));assertNotNull(s.enter("BIK123"));assertNull(s.enter("BIK456"));assertEquals(1,s.waitingCount());assertEquals("CASH",s.exit("BIK123","CASH").paymentMethod());assertFalse(slot.isAvailable());assertEquals("BIK456",s.activeTickets().getFirst().vehicle().getRegistrationNumber());assertEquals(0,s.waitingCount());}
 @Test void rejectsUnregisteredAndAlreadyParkedVehicle(){ParkingService s=new ParkingService();assertThrows(IllegalArgumentException.class,()->s.enter("ABC123"));s.register(new Bike("BIK123","Owner"));s.enter("BIK123");assertThrows(IllegalStateException.class,()->s.enter("BIK123"));}
 @Test void vehicleRatesAndValidation(){assertEquals("20.00",new Bike("BIK123","Owner").hourlyRate().toPlainString());assertThrows(IllegalArgumentException.class,()->new Car("!","Owner"));}
}
